-- لاوین (Lavin) — 0001 platform core
-- Ref: PRD §13, §14, §15, ADR-003, ADR-005
-- Conventions: UUID v7 generated by app (gen_random_uuid() fallback), all timestamps timestamptz UTC,
-- every business row carries tenant_id; optimistic locking via "version".

BEGIN;

-- Schema layout — every schema name is exactly 4 letters, one schema per domain (owner decision 2026-11-26):
--   orgs : tenant, business units, teams, work calendars, user profiles
--   auth : RBAC — permissions, roles, bindings, field policies, dual-approval requests, AD group mapping
--   conf : settings definitions/values, encrypted secret refs, feature flags
--   evnt : transactional outbox, consumer inbox, dead letters, idempotency keys
--   logs : append-only, hash-chained audit trail (INSERT-only grants)
--   cust : customer identity map (channel/phone ↔ CRM contact) and consent records
--   task : kanban boards, columns, tasks, transitions, dependencies
--   chnl : channel accounts (Bale/Rubika/Telegram/Email/Web), conversations, messages, receipts
--   call : PBX connections, calls, call legs, recording references
--   care : support tickets (cases/complaints) and SLA policies
--   know : RAG knowledge documents and chunks (pgvector)
--   aiml : prompt registry and AI response traces
--   reserved for later migrations: sale (CRM read projection), mktg (campaigns), meet (Jitsi), eval (EVAL engine)
-- External engines (Keycloak, Flowable, Corteza, Payload) use their own databases, not these schemas.

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;

CREATE SCHEMA IF NOT EXISTS orgs;
CREATE SCHEMA IF NOT EXISTS auth;
CREATE SCHEMA IF NOT EXISTS conf;
CREATE SCHEMA IF NOT EXISTS evnt;
CREATE SCHEMA IF NOT EXISTS logs;
CREATE SCHEMA IF NOT EXISTS cust;
CREATE SCHEMA IF NOT EXISTS task;
CREATE SCHEMA IF NOT EXISTS chnl;
CREATE SCHEMA IF NOT EXISTS call;
CREATE SCHEMA IF NOT EXISTS care;
CREATE SCHEMA IF NOT EXISTS know;
CREATE SCHEMA IF NOT EXISTS aiml;



-- ───────────────────────── org ─────────────────────────
CREATE TABLE orgs.tenant (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug          text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9-]{2,40}$'),
  name          text NOT NULL,
  locale        text NOT NULL DEFAULT 'fa-IR',
  timezone      text NOT NULL DEFAULT 'Asia/Tehran',
  currency      char(3) NOT NULL DEFAULT 'IRR',
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')),
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE orgs.business_unit (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id  uuid NOT NULL REFERENCES orgs.tenant(id),
  parent_id  uuid REFERENCES orgs.business_unit(id),
  name       text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, name)
);

CREATE TABLE orgs.team (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL REFERENCES orgs.tenant(id),
  business_unit_id uuid NOT NULL REFERENCES orgs.business_unit(id),
  name             text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, business_unit_id, name)
);

CREATE TABLE orgs.work_calendar (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES orgs.tenant(id),
  name        text NOT NULL,
  work_week   smallint[] NOT NULL DEFAULT '{6,0,1,2,3}', -- 0=Sunday … 6=Saturday (Sat–Wed)
  day_start   time NOT NULL DEFAULT '08:00',
  day_end     time NOT NULL DEFAULT '17:00',
  holidays    date[] NOT NULL DEFAULT '{}'
);

-- ───────────────────────── iam (profile only; credentials live in Keycloak) ─────────────────────────
CREATE TABLE orgs.user_profile (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL REFERENCES orgs.tenant(id),
  keycloak_sub     text NOT NULL,
  username         text NOT NULL,
  display_name     text NOT NULL,
  email            text,
  source           text NOT NULL CHECK (source IN ('ad','local','service')),
  business_unit_id uuid REFERENCES orgs.business_unit(id),
  locale           text,
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  last_login_at    timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, keycloak_sub)
);

CREATE TABLE orgs.team_member (
  team_id  uuid NOT NULL REFERENCES orgs.team(id),
  user_id  uuid NOT NULL REFERENCES orgs.user_profile(id),
  is_lead  boolean NOT NULL DEFAULT false,
  PRIMARY KEY (team_id, user_id)
);

-- ───────────────────────── authz ─────────────────────────
CREATE TABLE auth.permission (
  key          text PRIMARY KEY CHECK (key ~ '^[a-z_]+\.[a-z_]+\.[a-z_]+$'), -- module.resource.action
  module       text NOT NULL,
  description  text NOT NULL,
  sensitive    boolean NOT NULL DEFAULT false,      -- requires dual approval to grant
  max_scope    text NOT NULL DEFAULT 'global'
);

CREATE TABLE auth.role (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid REFERENCES orgs.tenant(id),      -- NULL = system template
  key         text NOT NULL,
  name_fa     text NOT NULL,
  is_template boolean NOT NULL DEFAULT false,
  version     int NOT NULL DEFAULT 1,
  UNIQUE NULLS NOT DISTINCT (tenant_id, key)
);

CREATE TYPE auth.scope_type AS ENUM ('global','tenant','business_unit','team','assigned','own');
CREATE TYPE auth.effect AS ENUM ('allow','deny');

CREATE TABLE auth.role_permission (
  role_id        uuid NOT NULL REFERENCES auth.role(id) ON DELETE CASCADE,
  permission_key text NOT NULL REFERENCES auth.permission(key),
  effect         auth.effect NOT NULL DEFAULT 'allow',
  default_scope  auth.scope_type NOT NULL DEFAULT 'team',
  PRIMARY KEY (role_id, permission_key)
);

CREATE TABLE auth.role_binding (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL REFERENCES orgs.tenant(id),
  principal_type text NOT NULL CHECK (principal_type IN ('user','group','service')),
  principal_id   text NOT NULL,                       -- user_profile.id | keycloak group path | client id
  role_id        uuid NOT NULL REFERENCES auth.role(id),
  scope_type     auth.scope_type NOT NULL,
  scope_id       uuid,                                -- bu/team id when applicable
  valid_until    timestamptz,
  granted_by     uuid,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CHECK ((scope_type IN ('business_unit','team')) = (scope_id IS NOT NULL))
);
CREATE INDEX ON auth.role_binding (tenant_id, principal_type, principal_id);

CREATE TABLE auth.field_policy (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL REFERENCES orgs.tenant(id),
  entity         text NOT NULL,                       -- e.g. crm.contact
  field          text NOT NULL,                       -- e.g. national_id
  required_perm  text NOT NULL REFERENCES auth.permission(key),
  mode           text NOT NULL CHECK (mode IN ('hide','mask')),
  UNIQUE (tenant_id, entity, field)
);

CREATE TABLE auth.change_request (                  -- dual approval for critical RBAC/settings changes
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES orgs.tenant(id),
  kind          text NOT NULL,                        -- role_binding.create | role.update | setting.change …
  payload       jsonb NOT NULL,
  requested_by  uuid NOT NULL,
  approved_by   uuid,
  status        text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','applied','expired')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  decided_at    timestamptz,
  CHECK (approved_by IS NULL OR approved_by <> requested_by)
);

CREATE TABLE auth.group_role_mapping (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES orgs.tenant(id),
  group_ref   text NOT NULL,                          -- AD DN or Keycloak group path
  role_id     uuid NOT NULL REFERENCES auth.role(id),
  scope_type  auth.scope_type NOT NULL,
  scope_id    uuid,
  UNIQUE NULLS NOT DISTINCT (tenant_id, group_ref, role_id, scope_type, scope_id)
);

-- ───────────────────────── audit (append-only, hash-chained) ─────────────────────────
CREATE TABLE logs.audit_event (
  seq            bigserial PRIMARY KEY,
  id             uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
  tenant_id      uuid NOT NULL,
  occurred_at    timestamptz NOT NULL DEFAULT now(),
  actor_type     text NOT NULL CHECK (actor_type IN ('user','service','system')),
  actor_id       text NOT NULL,
  action         text NOT NULL,                       -- permission key or verb
  entity_type    text NOT NULL,
  entity_id      text,
  outcome        text NOT NULL CHECK (outcome IN ('success','denied','error')),
  changes        jsonb,                               -- redacted diff
  correlation_id uuid NOT NULL,
  ip             inet,
  user_agent     text,
  prev_hash      bytea,
  hash           bytea NOT NULL
);
CREATE INDEX ON logs.audit_event (tenant_id, occurred_at DESC);
CREATE INDEX ON logs.audit_event (tenant_id, entity_type, entity_id);

CREATE FUNCTION logs.forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'logs.audit_event is append-only'; END $$;
CREATE TRIGGER audit_event_immutable BEFORE UPDATE OR DELETE ON logs.audit_event
  FOR EACH ROW EXECUTE FUNCTION logs.forbid_mutation();

-- ───────────────────────── settings / secrets / flags ─────────────────────────
CREATE TABLE conf.definition (
  key              text PRIMARY KEY CHECK (key ~ '^[a-z_]+(\.[a-z0-9_]+)+$'), -- namespace.key
  namespace        text NOT NULL,
  value_type       text NOT NULL CHECK (value_type IN ('string','int','bool','json','duration','url','secret_ref','enum')),
  json_schema      jsonb,
  scope            text NOT NULL CHECK (scope IN ('global','tenant','business_unit')),
  sensitivity      text NOT NULL DEFAULT 'normal' CHECK (sensitivity IN ('normal','sensitive','critical')),
  requires_restart boolean NOT NULL DEFAULT false,
  test_action      text,                              -- e.g. channels.test_connection
  required_perm    text NOT NULL REFERENCES auth.permission(key),
  default_value    jsonb,
  label_fa         text NOT NULL
);

CREATE TABLE conf.value (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key         text NOT NULL REFERENCES conf.definition(key),
  tenant_id   uuid REFERENCES orgs.tenant(id),
  scope_id    uuid,
  environment text NOT NULL DEFAULT 'prod' CHECK (environment IN ('dev','stage','prod')),
  value       jsonb NOT NULL,
  version     int NOT NULL,
  status      text NOT NULL CHECK (status IN ('draft','pending_approval','testing','active','superseded','failed','rolled_back')),
  actor_id    uuid NOT NULL,
  approved_by uuid,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (key, tenant_id, scope_id, environment, version)
);
CREATE UNIQUE INDEX config_one_active ON conf.value (key, tenant_id, scope_id, environment)
  NULLS NOT DISTINCT WHERE status = 'active';

CREATE TABLE conf.secret_ref (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid REFERENCES orgs.tenant(id),
  name          text NOT NULL,
  ciphertext    bytea NOT NULL,                       -- AES-256-GCM with DEK
  wrapped_dek   bytea NOT NULL,                       -- DEK wrapped by KEK (file/HSM/OpenBao)
  kek_id        text NOT NULL,
  fingerprint   text NOT NULL,                        -- last 4 + sha256 prefix, safe to display
  rotated_at    timestamptz NOT NULL DEFAULT now(),
  revoked_at    timestamptz,
  UNIQUE NULLS NOT DISTINCT (tenant_id, name)
);

CREATE TABLE conf.feature_flag (
  key        text NOT NULL,
  tenant_id  uuid REFERENCES orgs.tenant(id),
  enabled    boolean NOT NULL DEFAULT false,
  rules      jsonb,
  updated_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (key, tenant_id)
);

-- ───────────────────────── messaging: outbox / inbox / idempotency ─────────────────────────
CREATE TABLE evnt.outbox (
  id                uuid PRIMARY KEY,                  -- = event_id
  tenant_id         uuid NOT NULL,
  event_type        text NOT NULL CHECK (event_type ~ '\.v[0-9]+$'), -- lead.created.v1
  schema_version    int NOT NULL,
  aggregate_type    text NOT NULL,
  aggregate_id      uuid NOT NULL,
  aggregate_version bigint NOT NULL,
  occurred_at       timestamptz NOT NULL DEFAULT now(),
  correlation_id    uuid NOT NULL,
  causation_id      uuid,
  actor             jsonb NOT NULL,
  payload           jsonb NOT NULL,
  published_at      timestamptz,
  attempts          int NOT NULL DEFAULT 0,
  last_error        text
);
CREATE INDEX outbox_unpublished ON evnt.outbox (occurred_at) WHERE published_at IS NULL;

CREATE TABLE evnt.inbox (
  consumer     text NOT NULL,
  event_id     uuid NOT NULL,
  processed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (consumer, event_id)
);

CREATE TABLE evnt.dead_letter (
  id         bigserial PRIMARY KEY,
  consumer   text NOT NULL,
  event_id   uuid NOT NULL,
  envelope   jsonb NOT NULL,
  error      text NOT NULL,
  failed_at  timestamptz NOT NULL DEFAULT now(),
  replayed_at timestamptz
);

CREATE TABLE evnt.idempotency_key (
  tenant_id     uuid NOT NULL,
  principal_id  text NOT NULL,
  key           text NOT NULL,
  request_hash  bytea NOT NULL,
  response_code int,
  response_body jsonb,
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, principal_id, key)
);

-- ───────────────────────── identity mapping (§3.2 mandatory rule) ─────────────────────────
CREATE TABLE cust.identity (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES orgs.tenant(id),
  crm_contact_id text NOT NULL,                       -- id in CRM system of record (Corteza record id)
  identity_type text NOT NULL CHECK (identity_type IN ('phone','email','bale','rubika','telegram','webchat','pbx_caller')),
  identity_value text NOT NULL,                       -- normalized (E.164 for phones)
  confidence    numeric(3,2) NOT NULL CHECK (confidence BETWEEN 0 AND 1),
  verification  text NOT NULL CHECK (verification IN ('unverified','user_confirmed','agent_confirmed','otp_verified')),
  linked_by     text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  unlinked_at   timestamptz
);
CREATE UNIQUE INDEX contact_identity_active
  ON cust.identity (tenant_id, identity_type, identity_value, crm_contact_id) WHERE unlinked_at IS NULL;
CREATE INDEX ON cust.identity (tenant_id, identity_type, identity_value) WHERE unlinked_at IS NULL;

CREATE TABLE cust.consent (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES orgs.tenant(id),
  crm_contact_id text,
  identity_id   uuid REFERENCES cust.identity(id),
  purpose       text NOT NULL CHECK (purpose IN ('marketing','service','recording','ai_processing')),
  channel       text,
  granted       boolean NOT NULL,
  evidence      jsonb NOT NULL,                       -- message id / form / call id
  recorded_at   timestamptz NOT NULL DEFAULT now()
);

-- ───────────────────────── tasks (board projection + standalone) ─────────────────────────
CREATE TABLE task.board (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES orgs.tenant(id),
  key         text NOT NULL,
  name        text NOT NULL,
  owner_team  uuid REFERENCES orgs.team(id),
  swimlane_by text CHECK (swimlane_by IN ('team','campaign','account','assignee','none')),
  version     int NOT NULL DEFAULT 1,
  UNIQUE (tenant_id, key)
);

CREATE TABLE task.board_column (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  board_id    uuid NOT NULL REFERENCES task.board(id) ON DELETE CASCADE,
  key         text NOT NULL,
  name        text NOT NULL,
  position    int NOT NULL,
  wip_limit   int,
  is_terminal boolean NOT NULL DEFAULT false,
  bpm_outcome text,                                   -- maps drop target to Flowable outcome
  UNIQUE (board_id, key)
);

CREATE TABLE task.task (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL REFERENCES orgs.tenant(id),
  board_id         uuid NOT NULL REFERENCES task.board(id),
  column_id        uuid NOT NULL REFERENCES task.board_column(id),
  kind             text NOT NULL CHECK (kind IN ('standalone','bpm')),
  flowable_task_id text UNIQUE,
  process_instance_id text,
  title            text NOT NULL,
  description      text,
  priority         smallint NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5),
  due_at           timestamptz,
  sla_due_at       timestamptz,
  assignee_id      uuid REFERENCES orgs.user_profile(id),
  team_id          uuid REFERENCES orgs.team(id),
  business_unit_id uuid REFERENCES orgs.business_unit(id),
  owner_id         uuid REFERENCES orgs.user_profile(id),
  related_type     text,                              -- lead|deal|case|content|campaign
  related_id       text,
  parent_id        uuid REFERENCES task.task(id),
  position         numeric NOT NULL DEFAULT 0,
  version          bigint NOT NULL DEFAULT 1,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CHECK ((kind = 'bpm') = (flowable_task_id IS NOT NULL))
);
CREATE INDEX ON task.task (tenant_id, board_id, column_id, position);
CREATE INDEX ON task.task (tenant_id, assignee_id);
CREATE INDEX ON task.task (tenant_id, team_id);

CREATE TABLE task.transition (
  id            bigserial PRIMARY KEY,
  task_id       uuid NOT NULL REFERENCES task.task(id),
  from_column   uuid NOT NULL,
  to_column     uuid NOT NULL,
  actor_id      uuid NOT NULL,
  result        text NOT NULL CHECK (result IN ('accepted','rejected')),
  reason        text,
  correlation_id uuid NOT NULL,
  at            timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE task.dependency (
  task_id       uuid NOT NULL REFERENCES task.task(id) ON DELETE CASCADE,
  depends_on_id uuid NOT NULL REFERENCES task.task(id) ON DELETE CASCADE,
  PRIMARY KEY (task_id, depends_on_id),
  CHECK (task_id <> depends_on_id)
);

-- ───────────────────────── channels ─────────────────────────
CREATE TABLE chnl.account (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL REFERENCES orgs.tenant(id),
  provider        text NOT NULL CHECK (provider IN ('bale','rubika','telegram','email','webchat')),
  alias           text NOT NULL UNIQUE,               -- random, used in webhook path
  display_name    text NOT NULL,
  credential_ref  uuid REFERENCES conf.secret_ref(id),
  webhook_secret_ref uuid REFERENCES conf.secret_ref(id),
  mode            text NOT NULL DEFAULT 'webhook' CHECK (mode IN ('webhook','polling')),
  capabilities    jsonb NOT NULL DEFAULT '{}',        -- {"text":{"supported":true,"verified_at":"…"}, …}
  api_version     text,
  status          text NOT NULL DEFAULT 'disabled' CHECK (status IN ('active','disabled','degraded')),
  business_unit_id uuid REFERENCES orgs.business_unit(id),
  config_version  int NOT NULL DEFAULT 1
);

CREATE TABLE chnl.conversation (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL REFERENCES orgs.tenant(id),
  account_id       uuid NOT NULL REFERENCES chnl.account(id),
  external_chat_id text NOT NULL,
  identity_id      uuid REFERENCES cust.identity(id),
  assignee_id      uuid REFERENCES orgs.user_profile(id),
  team_id          uuid REFERENCES orgs.team(id),
  handled_by       text NOT NULL DEFAULT 'ai' CHECK (handled_by IN ('ai','human','closed')),
  sla_due_at       timestamptz,
  tags             text[] NOT NULL DEFAULT '{}',
  last_message_at  timestamptz,
  UNIQUE (tenant_id, account_id, external_chat_id)
);

CREATE TABLE chnl.message (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          uuid NOT NULL,
  conversation_id    uuid NOT NULL REFERENCES chnl.conversation(id),
  account_id         uuid NOT NULL REFERENCES chnl.account(id),
  direction          text NOT NULL CHECK (direction IN ('in','out','note')),
  external_message_id text,
  client_msg_id      uuid,                            -- outbound idempotency
  author_type        text NOT NULL CHECK (author_type IN ('contact','agent','ai','system')),
  author_id          text,
  body               text,
  attachments        jsonb NOT NULL DEFAULT '[]',
  ai_trace_id        uuid,
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX message_inbound_dedupe ON chnl.message (tenant_id, account_id, external_message_id)
  WHERE direction = 'in';
CREATE UNIQUE INDEX message_outbound_idem ON chnl.message (conversation_id, client_msg_id)
  WHERE client_msg_id IS NOT NULL;

CREATE TABLE chnl.delivery_receipt (
  id          bigserial PRIMARY KEY,
  message_id  uuid NOT NULL REFERENCES chnl.message(id),
  status      text NOT NULL CHECK (status IN ('queued','sent','delivered','read','failed','unsupported')),
  provider_ref text,
  error       text,
  at          timestamptz NOT NULL DEFAULT now()
);

-- ───────────────────────── cti ─────────────────────────
CREATE TABLE call.pbx_connection (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL REFERENCES orgs.tenant(id),
  name            text NOT NULL,
  driver          text NOT NULL DEFAULT 'asterisk_ami' CHECK (driver IN ('asterisk_ami','asterisk_ari')),
  host            text NOT NULL,
  port            int NOT NULL,
  tls             boolean NOT NULL DEFAULT true,
  events_cred_ref uuid REFERENCES conf.secret_ref(id),
  control_cred_ref uuid REFERENCES conf.secret_ref(id),
  timezone        text NOT NULL DEFAULT 'Asia/Tehran',
  reconnect_policy jsonb NOT NULL DEFAULT '{"base_ms":1000,"max_ms":60000}',
  status          text NOT NULL DEFAULT 'disabled' CHECK (status IN ('connected','disconnected','disabled','error')),
  business_unit_id uuid REFERENCES orgs.business_unit(id),
  UNIQUE (tenant_id, name)
);

CREATE TABLE call.call (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL,
  connection_id   uuid NOT NULL REFERENCES call.pbx_connection(id),
  linkedid        text NOT NULL,
  direction       text NOT NULL CHECK (direction IN ('inbound','outbound','internal')),
  caller_number   text,                                -- E.164
  callee_number   text,
  queue           text,
  extension       text,
  agent_user_id   uuid REFERENCES orgs.user_profile(id),
  started_at      timestamptz NOT NULL,
  answered_at     timestamptz,
  ended_at        timestamptz,
  disposition     text CHECK (disposition IN ('answered','missed','busy','failed','voicemail','transferred')),
  identity_id     uuid REFERENCES cust.identity(id),
  match_confidence numeric(3,2),
  related_type    text,
  related_id      text,
  version         bigint NOT NULL DEFAULT 1,
  UNIQUE (connection_id, linkedid)
);

CREATE TABLE call.leg (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  call_id       uuid NOT NULL REFERENCES call.call(id),
  uniqueid      text NOT NULL,
  channel       text,
  extension     text,
  started_at    timestamptz,
  ended_at      timestamptz,
  UNIQUE (call_id, uniqueid)
);

CREATE TABLE call.recording (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL,
  call_id       uuid NOT NULL REFERENCES call.call(id),
  storage       text NOT NULL CHECK (storage IN ('pbx','object_store')),
  locator       text NOT NULL,                        -- never exposed directly
  sha256        text,
  consent_id    uuid REFERENCES cust.consent(id),
  retain_until  timestamptz NOT NULL,
  encrypted     boolean NOT NULL DEFAULT true
);

-- ───────────────────────── support ─────────────────────────
CREATE TABLE care.sla_policy (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES orgs.tenant(id),
  name          text NOT NULL,
  severity      text NOT NULL CHECK (severity IN ('critical','high','medium','low')),
  first_response interval NOT NULL,
  resolution     interval NOT NULL,
  calendar_id   uuid REFERENCES orgs.work_calendar(id)
);

CREATE TABLE care.ticket (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL REFERENCES orgs.tenant(id),
  number           bigint GENERATED ALWAYS AS IDENTITY,
  crm_contact_id   text,
  crm_account_id   text,
  title            text NOT NULL,
  category         text NOT NULL DEFAULT 'complaint',
  severity         text CHECK (severity IN ('critical','high','medium','low')),
  status           text NOT NULL DEFAULT 'new' CHECK (status IN ('new','assigned','investigating','awaiting_supervisor','responded','closed','reopened')),
  source           text NOT NULL CHECK (source IN ('phone','bale','rubika','telegram','email','webchat','manual','api')),
  source_ref       text,
  assignee_id      uuid REFERENCES orgs.user_profile(id),
  team_id          uuid REFERENCES orgs.team(id),
  business_unit_id uuid REFERENCES orgs.business_unit(id),
  sla_policy_id    uuid REFERENCES care.sla_policy(id),
  process_instance_id text,
  csat             smallint CHECK (csat BETWEEN 1 AND 5),
  version          bigint NOT NULL DEFAULT 1,
  created_at       timestamptz NOT NULL DEFAULT now(),
  closed_at        timestamptz
);

-- ───────────────────────── ai / knowledge ─────────────────────────
CREATE TABLE know.document (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL REFERENCES orgs.tenant(id),
  title           text NOT NULL,
  source_type     text NOT NULL CHECK (source_type IN ('cms','upload','url','manual')),
  source_ref      text,
  version         int NOT NULL DEFAULT 1,
  classification  text NOT NULL DEFAULT 'internal' CHECK (classification IN ('public','internal','confidential','restricted')),
  acl_scope_type  auth.scope_type NOT NULL DEFAULT 'tenant',
  acl_scope_ids   uuid[] NOT NULL DEFAULT '{}',
  status          text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','indexed','failed','archived')),
  valid_until     timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE know.chunk (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL,
  document_id    uuid NOT NULL REFERENCES know.document(id) ON DELETE CASCADE,
  doc_version    int NOT NULL,
  chunk_index    int NOT NULL,
  content        text NOT NULL,
  tsv            tsvector NOT NULL,                   -- built by app after Persian normalization
  embedding      vector(1024),
  -- denormalized ACL so filtering happens before ranking (AT-09)
  classification text NOT NULL,
  acl_scope_type auth.scope_type NOT NULL,
  acl_scope_ids  uuid[] NOT NULL,
  UNIQUE (document_id, doc_version, chunk_index)
);
CREATE INDEX knowledge_chunk_hnsw ON know.chunk USING hnsw (embedding vector_cosine_ops);
CREATE INDEX knowledge_chunk_tsv ON know.chunk USING gin (tsv);
CREATE INDEX knowledge_chunk_acl ON know.chunk USING gin (acl_scope_ids);

CREATE TABLE aiml.prompt_version (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES orgs.tenant(id),
  prompt_key  text NOT NULL,
  version     int NOT NULL,
  body        text NOT NULL,
  model_ref   text NOT NULL,
  params      jsonb NOT NULL DEFAULT '{}',
  status      text NOT NULL CHECK (status IN ('draft','candidate','active','retired','rolled_back')),
  eval_run_id uuid,
  created_by  uuid NOT NULL,
  approved_by uuid,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, prompt_key, version)
);
CREATE UNIQUE INDEX prompt_one_active ON aiml.prompt_version (tenant_id, prompt_key) WHERE status = 'active';

CREATE TABLE aiml.response_trace (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL,
  correlation_id uuid NOT NULL,
  prompt_version_id uuid REFERENCES aiml.prompt_version(id),
  model_version  text NOT NULL,
  input_tokens   int,
  output_tokens  int,
  duration_ms    int,
  retrieval_ids  uuid[] NOT NULL DEFAULT '{}',
  citations      jsonb NOT NULL DEFAULT '[]',
  safety_flags   text[] NOT NULL DEFAULT '{}',
  created_at     timestamptz NOT NULL DEFAULT now()
);

COMMIT;
